#!/usr/bin/env python3
"""Check repository discipline without changing GitHub settings or running generators."""

from __future__ import annotations

import argparse
import json
import re
import sys
from datetime import date
from pathlib import Path
from typing import Any

SECTIONS = (
    "Scope",
    "BDD acceptance",
    "Tests and evidence",
    "Provenance",
    "Generated files",
    "Owner and exceptions",
)


def render_template(owner: str) -> str:
    """The template is generated deterministically; no network or timestamps."""
    return (
        """<!-- Generated by tools/check_repo_hygiene.py --write-template; do not edit. -->
## Scope
<!-- State the bounded change and non-goals; link the issue/specification. -->

## BDD acceptance
<!-- Given a concrete state, When the changed operation runs, Then an observable result follows. -->

## Tests and evidence
<!-- Link tests and evidence; list commands, outcomes and unavailable checks. -->

## Provenance
<!-- Link provenance.json and describe original/imported source, rights and notices. -->

## Generated files
<!-- List changed generated outputs and regeneration/check commands, or N/A with a reason. -->

## Owner and exceptions
<!-- Name the accountable owner; default repository owner: @"""
        + owner
        + """.
List exception IDs from repository-hygiene.json, or explicitly state none.
An exception requires a reason, accountable owner, issue link and UTC expiry. -->
"""
    )


def nonempty(value: object) -> bool:
    return isinstance(value, str) and bool(value.strip())


def validate_policy(policy: dict[str, Any], today: date) -> list[str]:
    errors = []
    if policy.get("schema_version") != 1:
        errors.append("policy schema_version must be 1")
    if not re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9-]*", str(policy.get("accountable_owner", ""))
    ):
        errors.append("accountable_owner must name a GitHub account")
    if policy.get("required_pr_sections") != list(SECTIONS):
        errors.append("required PR sections drifted")
    exceptions = policy.get("exceptions")
    if not isinstance(exceptions, list):
        return errors + ["exceptions must be a list"]
    ids = set()
    for item in exceptions:
        if not isinstance(item, dict):
            errors.append("exception must be an object")
            continue
        identifier = item.get("id")
        if not nonempty(identifier) or identifier in ids:
            errors.append("exception needs a unique nonempty id")
        else:
            ids.add(identifier)
        for field in ("owner", "reason", "scope"):
            if not nonempty(item.get(field)):
                errors.append(f"exception {field} missing")
        if not re.fullmatch(
            r"https://github\.com/[^/]+/[^/]+/issues/[1-9][0-9]*",
            str(item.get("issue", "")),
        ):
            errors.append("exception needs an issue URL")
        try:
            expires = date.fromisoformat(item["expires_utc"])
            if expires <= today:
                errors.append("exception expired (expiry date is exclusive, UTC)")
        except (KeyError, TypeError, ValueError):
            errors.append("exception needs ISO expires_utc date")
    return errors


def check_pr_body(text: str, policy: dict[str, Any]) -> list[str]:
    # Template comments do not count as supplied evidence.
    text = re.sub(r"<!--.*?-->", "", text, flags=re.S)
    parts = re.split(r"^## (.+)\s*$", text, flags=re.M)
    sections = {parts[i].strip(): parts[i + 1].strip() for i in range(1, len(parts), 2)}
    errors = []
    for heading in SECTIONS:
        if not sections.get(heading) or sections[heading].lower() in {
            "todo",
            "tbd",
            "n/a",
            "none",
        }:
            errors.append(f"PR section needs concrete content: {heading}")
    bdd = sections.get("BDD acceptance", "")
    if not all(
        re.search(r"\b" + word + r"\b", bdd, re.I) for word in ("Given", "When", "Then")
    ):
        errors.append("BDD acceptance needs Given/When/Then")
    for heading in ("Scope", "Tests and evidence", "Provenance"):
        if not re.search(r"\[[^\]]+\]\([^)]+\)|https://\S+", sections.get(heading, "")):
            errors.append(f"PR section needs a source/test link: {heading}")
    owner = sections.get("Owner and exceptions", "")
    if not re.search(r"@[A-Za-z0-9][A-Za-z0-9-]*", owner):
        errors.append("PR needs an accountable @owner")
    if not re.search(r"\bnone\b", owner, re.I):
        if not any(
            item.get("id", "") in owner for item in policy.get("exceptions", [])
        ):
            errors.append(
                "PR must name a declared exception ID or explicitly state none"
            )
    return errors


def check(root: Path, pr_body: Path | None = None) -> list[str]:
    try:
        policy = json.loads((root / "repository-hygiene.json").read_text())
        if not isinstance(policy, dict):
            return ["policy must be an object"]
        from datetime import datetime, timezone

        errors = validate_policy(policy, datetime.now(timezone.utc).date())
        template = root / ".github/PULL_REQUEST_TEMPLATE.md"
        if template.read_text() != render_template(
            str(policy.get("accountable_owner", ""))
        ):
            errors.append(
                "generated PR template drift: run --write-template and review diff"
            )
        provenance = json.loads((root / "provenance.json").read_text())
        if not isinstance(provenance, dict) or provenance.get("schema_version") != 1:
            errors.append("provenance.json needs existing version-1 provenance object")
        if not nonempty(provenance.get("new_files")) or not nonempty(
            provenance.get("license_status")
        ):
            errors.append("provenance missing new_files/license_status")
        if pr_body is not None:
            errors.extend(check_pr_body(pr_body.read_text(), policy))
        return errors
    except (OSError, ValueError, TypeError) as error:
        return [f"required repository hygiene input unreadable: {type(error).__name__}"]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--pr-body",
        type=Path,
        help="Explicit local PR-body file; never fetched automatically",
    )
    parser.add_argument(
        "--write-template",
        action="store_true",
        help="Regenerate only the tracked PR template",
    )
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    if args.write_template:
        policy = json.loads((root / "repository-hygiene.json").read_text())
        (root / ".github/PULL_REQUEST_TEMPLATE.md").write_text(
            render_template(policy["accountable_owner"])
        )
    errors = check(root, args.pr_body)
    for error in errors:
        print("repository hygiene: " + error, file=sys.stderr)
    if not errors:
        print(
            "repository hygiene passed; PR body "
            + ("checked" if args.pr_body else "not supplied/not checked")
        )
    return bool(errors)


if __name__ == "__main__":
    raise SystemExit(main())
